// 'de-DE' → 'de'; unknown → 'en'
export function normLang(code) {
  const l = String(code || '').toLowerCase().slice(0, 2);
  return LANGS[l] ? l : 'en';
}

// config.language wins, else HA user language (hass.locale.language, older HA: hass.language), else 'en'.
export function pickLang(config, hass) {
  return normLang(config?.language || hass?.locale?.language || hass?.language || 'en');
}

export function t(lang, key, vars = {}) {
  const s = LANGS[normLang(lang)]?.[key] ?? LANGS.en[key] ?? key;
  return s.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? String(vars[k]) : m));
}
